    registry的title欄位(卡片顯示用)，不受影響。"""
    for sep in ("｜", "|", "—", "－", "–", " - ", "："):
        if sep in title:
            return title.split(sep, 1)[0].strip()
    return title


def slugify_title(title: str) -> str:
    from pypinyin import lazy_pinyin
